-- Minimal, local-only PostgreSQL schema preserving the production signing column
-- types, constraints and deliberately broad pre-hardening grants/RLS behavior.
create role anon;
create role authenticated;
create role service_role bypassrls;
create table public.orgs(id uuid primary key);
create table public.contacts(id uuid primary key,org_id uuid not null);
create table public.memberships(id uuid primary key default gen_random_uuid(),org_id uuid not null,user_id uuid not null,status text not null);
create table public.documents (
 id uuid primary key default gen_random_uuid(), org_id uuid not null references public.orgs(id),
 project_id uuid, prospect_id uuid, document_type text not null default 'contract', title text not null,
 status text not null default 'draft' check(status in ('draft','sent','signed','voided','expired')),
 source_file_id uuid not null, executed_file_id uuid, current_revision integer not null default 1,
 source_entity_type text, source_entity_id uuid, metadata jsonb not null default '{}',
 created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.envelopes (
 id uuid primary key default gen_random_uuid(), org_id uuid not null references public.orgs(id), document_id uuid not null references public.documents(id),
 document_revision integer not null default 1, status text not null default 'draft' check(status in ('draft','sent','partially_signed','executed','voided','expired')),
 expires_at timestamptz, sent_at timestamptz, executed_at timestamptz, voided_at timestamptz,
 metadata jsonb not null default '{}', updated_at timestamptz not null default now(), created_at timestamptz not null default now(),
 project_id uuid, source_entity_type text, source_entity_id uuid, created_by uuid, subject text, message text
);
create table public.document_fields (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, document_id uuid not null references public.documents(id),
 revision integer not null default 1, page_index integer not null check(page_index>=0),
 field_type text not null check(field_type in ('signature','initials','text','date','checkbox','name')),
 label text, required boolean not null default true, signer_role text not null default 'client',
 x numeric not null check(x>=0 and x<=1), y numeric not null check(y>=0 and y<=1),
 w numeric not null check(w>0 and w<=1), h numeric not null check(h>0 and h<=1),
 sort_order integer not null default 0, metadata jsonb not null default '{}', created_at timestamptz not null default now()
);
create table public.document_signing_requests (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, document_id uuid not null references public.documents(id), revision integer not null,
 token_hash text not null, status text not null default 'draft' check(status in ('draft','sent','viewed','signed','voided','expired')),
 recipient_contact_id uuid, sent_to_email text, sent_at timestamptz, viewed_at timestamptz, signed_at timestamptz, expires_at timestamptz,
 max_uses integer not null default 1, used_count integer not null default 0,
 group_id uuid, envelope_id uuid, envelope_recipient_id uuid, signer_role text not null default 'client',
 sequence integer not null default 1 check(sequence>=1), required boolean not null default true, created_by uuid,
 created_at timestamptz not null default now(), check(max_uses>=1 and used_count>=0 and used_count<=max_uses)
);
create table public.document_signatures (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, signing_request_id uuid not null references public.document_signing_requests(id),
 document_id uuid not null references public.documents(id), revision integer not null, signer_name text, signer_email text, signer_ip inet,
 user_agent text, consent_text text not null, values jsonb not null default '{}', audit_data jsonb not null default '{}', created_at timestamptz not null default now()
);
create table public.events (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, event_type text not null, entity_type text, entity_id uuid,
 payload jsonb not null default '{}', channel text not null default 'activity', created_at timestamptz not null default now()
);
create table public.outbox (
 id bigint generated by default as identity primary key, org_id uuid not null, job_type text not null,
 status text not null default 'pending', payload jsonb not null default '{}', dedupe_key text,
 run_at timestamptz not null default now(), retry_count integer not null default 0
);
create unique index outbox_pending_dedupe on public.outbox(org_id,dedupe_key) where status='pending' and dedupe_key is not null;
create table public.files (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, project_id uuid, prospect_id uuid,
 file_name text not null, storage_path text not null, mime_type text, size_bytes bigint, visibility text, category text,
 source text, uploaded_by uuid, metadata jsonb not null default '{}', current_version_id uuid
);
create table public.doc_versions (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, file_id uuid not null references public.files(id),
 version_number integer not null default 1, label text, storage_path text, file_name text, mime_type text, size_bytes bigint, created_by uuid
);
create table public.envelope_recipients (
 id uuid primary key default gen_random_uuid(), org_id uuid not null, envelope_id uuid not null references public.envelopes(id),
 email text, name text, role text not null default 'signer', signer_role text, sequence integer not null default 1, required boolean not null default true,
 recipient_type text not null default 'external_email',contact_id uuid,user_id uuid,metadata jsonb not null default '{}'
);
alter table public.document_signatures enable row level security;
alter table public.events enable row level security;
-- Simulate a qualifying member, so tests prove mutation is prohibited even when
-- the existing permissive tenant policy would grant access.
create policy document_signatures_access on public.document_signatures using(true) with check(true);
create policy events_access on public.events using(true) with check(true);
grant usage on schema public to anon,authenticated,service_role;
grant all on all tables in schema public to anon,authenticated,service_role;
grant usage,select on all sequences in schema public to service_role;
